import '../../../services/auth/auth_service.dart';
import '../../../services/personal_ai/skill_coach_service.dart';
class AurenSkillCoachScreen extends StatefulWidget{const AurenSkillCoachScreen({super.key});@override State<AurenSkillCoachScreen> createState()=>_AurenSkillCoachScreenState();}
class _AurenSkillCoachScreenState extends State<AurenSkillCoachScreen>{final _auth=FirebaseAurenAuthService();final _service=AurenSkillCoachService();final _skill=TextEditingController();Future<AurenSkillCoachPlan>? _future;@override void initState(){super.initState();_load();}void _load(){final uid=_auth.currentUserId;if(uid!=null)setState(()=>_future=_service.build(uid,skill:_skill.text));}@override void dispose(){_skill.dispose();super.dispose();}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Skill Coach')),body:FutureBuilder<AurenSkillCoachPlan>(future:_future,builder:(context,s){if(s.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:Text('تعذر بناء خطة التدريب: '+s.error.toString()));final p=s.data;if(p==null)return const SizedBox.shrink();return ListView(padding:const EdgeInsets.all(16),children:[const Text('Skill Coach',style:TextStyle(fontSize:26,fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('مدرب عملي يربط المهارة بهدفك ويحوّلها إلى تطبيق قابل للقياس.'),const SizedBox(height:16),TextField(controller:_skill,decoration:const InputDecoration(labelText:'المهارة',hintText:'مثال: التسويق الرقمي')),FilledButton.icon(onPressed:_load,icon:const Icon(Icons.auto_awesome),label:const Text('ابنِ خطة التدريب')),const SizedBox(height:16),Card(child:ListTile(title:Text(p.skill),subtitle:Text('الهدف: '+p.goalTitle),trailing:Text(p.level))),_section('نقاط القوة',p.strengths),_section('ما يحتاج تطويرًا',p.gaps),_section('خطوات التدريب',p.actions)]);});}Widget _section(String title,List<String> items)=>Card(child:ExpansionTile(initiallyExpanded:true,title:Text(title),children:items.map((x)=>ListTile(leading:const Icon(Icons.check_circle_outline),title:Text(x))).toList()));}